void Solver::rephase() {
    rephases = 0;
    threshold *= 0.95;
    rephase_limit += 4096;
    // Update saved phases based on local_best or random with different probabilities
    int phase_rand = rand() % 100;
    if (phase_rand < 70) {
        // 70% chance: set saved to local_best (exploitation)
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (phase_rand < 80) {
        // 10% chance: set saved to opposite of local_best (diversification)
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_rand < 95) {
        // 15% chance: random phase
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        // 5% chance: clear saved (let VSIDS decide polarity)
        for (int i = 1; i <= vars; i++) saved[i] = 0;
    }
}
